(function(w,d){var dark=false,known=false;try{if(w.parent!==w){var r=w.parent.document.documentElement;if(r.classList.contains('vd-workspace-dark')||r.classList.contains('vd-workspace-light')){dark=r.classList.contains('vd-workspace-dark');known=true;}}}catch(e){}if(!known){try{var mobile=w.matchMedia('(max-width:767px)').matches,p=w.localStorage.getItem(mobile?'verdict-mobile-appearance-v2':'verdict-workspace-theme');dark=p==='dark'||(p!=='light'&&w.matchMedia('(prefers-color-scheme:dark)').matches);}catch(e){}}var r=d.documentElement;r.classList.toggle('vd-workspace-dark',dark);r.classList.toggle('vd-workspace-light',!dark);r.style.backgroundColor=dark?'#08090b':'#ffffff';r.style.colorScheme=dark?'dark':'light';})(window,document);